import { API_VERSION_PREFIX } from '06_shared/constants/api';
/**
 * Ends the session on the server: the access token stops working at once and
 * the refresh cookie is cleared. Plain fetch, not the RTK base query — that
 * one retries a 403 through a token refresh and would sign the user back in.
 * Fire-and-forget: the local sign-out must not wait for or depend on it.
 */
export const revokeSession = async (authorization) => {
    try {
        await fetch(`${__API_URL__}${API_VERSION_PREFIX}/auth/logout`, {
            method: 'POST',
            credentials: 'include',
            headers: { authorization },
        });
    }
    catch (e) {
        console.error('Error revoking the session', e);
    }
};
